import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { BrowserModule } from '@angular/platform-browser';
import { Routes, RouterModule } from '@angular/router';

// ! component
import { IndexComponent } from './pages/index/index.component';
import { ProductsComponent } from './pages/products/products/products.component';
import { ProductComponent } from './pages/products/product/product.component';
import { SolutionsComponent } from './pages/solutions/solutions/solutions.component';
import { SolutionExploreComponent } from './pages/solutions/solution-explore/solution-explore.component';
import { SuccessComponent } from './pages/solutions/success/success.component';
import { AboutkypageComponent } from './pages/aboutpages/aboutkypage/aboutkypage.component';
import { NewsComponent } from './pages/news/news/news.component';
import { NewsCenterComponent } from './pages/news/news-center/news-center.component';
import { HumanRecruitComponent } from './pages/recruitpages/human-recruit/human-recruit.component';
import { PageNotFoundComponent } from './pages/page-not-found/page-not-found.component';
import { PrivacyComponent } from './pages/claims/privacy/privacy.component';
import { InfoSecurityComponent } from './pages/claims/info-security/info-security.component';
import { CopyrightComponent } from './pages/claims/copyright/copyright.component';
import { SecondTeamsFormComponent } from './pages/recruitpages/second-teams-form/second-teams-form.component';

const routes: Routes = [
	// ** web 2.0
	{ path: '', component: IndexComponent, data: { title: '首頁' } },
	{ path: 'aboutKunYu', component: AboutkypageComponent, data: { title: '關於坤侑' } },
	{ path: 'newsCenter', component: NewsCenterComponent, data: { title: '新聞中心' } },
	{ path: 'teamsForm', component: HumanRecruitComponent, data: { title: '團拆表單' } },
	{ path: 'secondTeamsForm', component: SecondTeamsFormComponent, data: { title: '團拆表單' } },
	{ path: 'newsCenter/:type/:title', component: NewsComponent },
	{ path: 'products', component: ProductsComponent, data: { title: '產品服務' } },
	{ path: 'products/:title', component: ProductComponent },
	{ path: 'solutions', component: SolutionsComponent, data: { title: '解決方案' } },
	{ path: 'solutions/explore/:keyword', component: SolutionExploreComponent },
	{ path: 'solutions/explore', component: SolutionExploreComponent, data: { title: '各個領域的解決方案' } },
	{ path: 'success/:title', component: SuccessComponent },
	{ path: 'privacy', component: PrivacyComponent },
	{ path: 'infoSecurity', component: InfoSecurityComponent },
	{ path: 'copyright', component: CopyrightComponent },
	{ path: 'page-not-found', component: PageNotFoundComponent, data: { title: '頁面不存在' } },
	{ path: '**', redirectTo: 'page-not-found' },
];

@NgModule({
	imports: [
		CommonModule,
		BrowserModule,
		RouterModule.forRoot(routes, {
			scrollPositionRestoration: 'top',
		}),
	],
	exports: [],
})
export class AppRoutingModule {}
