import { Injectable } from '@angular/core';
import { createClient, SupabaseClient } from '@supabase/supabase-js';

const supabaseUrl = 'https://ldtiqtwoalwkalbhqkzp.supabase.co';
const supabaseKey = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImxkdGlxdHdvYWx3a2FsYmhxa3pwIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NDY1OTk1MjIsImV4cCI6MjA2MjE3NTUyMn0.ZOTG2AAfjo8GZq5RVtKj6WMSVYN-xp4jxeYwECVre9M';

@Injectable({
	providedIn: 'root',
})
export class SupabaseService {
	private supabase: SupabaseClient;

	constructor() {
		this.supabase = createClient(supabaseUrl, supabaseKey, {
			auth: {
			  autoRefreshToken: false, // 關掉自動刷新
			  persistSession: false    // 關掉 localStorage 儲存
			}
		});
	}

	getTeams() {
		return this.supabase.from('BAS_026_20260124').select('*').or('isLock.eq.false,isLock.is.null').order('id', { ascending: true });
	}

	getTeamsById(ids) {
		return this.supabase.from('BAS_026_20260124').select('*').in('id', ids);;
	}

	updateTeamInfo(ids: any, param) {
		return this.supabase
		.from('BAS_026_20260124')
		.update(param)
		.in('id', ids)
		.select();
	}

	// 檢查折扣代碼是否存在且尚未被使用
	checkDiscountCode(discountCode) {
		return this.supabase.from('Discount_Code').select('*').eq('discountCode', discountCode).eq('isUsed', false);
	}

	// 將使用過之折扣代碼註銷為已使用
	updateDiscountCodeToIsUsed(discountCode, personName) {
		return this.supabase
		.from('Discount_Code')
		.update({ isUsed: true, personName: personName })
		.eq('discountCode', discountCode);
	}
}
